# PTX source for fp16 matrix‑vector multiplication (A @ B)
PTX_SOURCE = r"""
.version 7.2
.target sm_80
.address_size 64

.visible .entry matvec_fp16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    // ------------------------------
    // Register declarations
    // ------------------------------
    .reg .pred   %p<3>;
    .reg .b32    %r<12>;
    .reg .b64    %rd<12>;
    .reg .f32    %f<6>;
    .reg .f16    %h<2>;

    // ------------------------------
    // Load kernel parameters
    // ------------------------------
    ld.param.u64    %rd1, [A_ptr];
    ld.param.u64    %rd2, [B_ptr];
    ld.param.u64    %rd3, [C_ptr];
    ld.param.u32    %r1,  [M];
    ld.param.u32    %r2,  [K];

    // ------------------------------
    // Thread/block indices
    // ------------------------------
    mov.u32 %r3, %ctaid.x;    // row index = blockIdx.x
    mov.u32 %r4, %tid.x;      // lane index = threadIdx.x

    // if (row >= M) return;
    setp.ge.u32 %p1, %r3, %r1;
    @%p1 ret;

    // ------------------------------
    // Compute base pointer for this row of A
    // ------------------------------
    // row_offset (elements) = row * K
    mul.wide.u32 %rd4, %r3, %r2;
    // byte offset = row_offset * sizeof(fp16) = *2
    mul.wide.u32 %rd5, %rd4, 2;
    // A_row_ptr = A_ptr + byte_offset
    add.u64 %rd6, %rd1, %rd5;

    // ------------------------------
    // Accumulate dot‑product in FP32
    // ------------------------------
    mov.f32 %f0, 0f00000000;          // sum = 0.0f

    // i = threadIdx.x; while (i < K) { i += blockDim.x }
    mov.u32 %r5, %r2;                 // K
    mov.u32 %r6, %r4;                 // i = threadIdx.x

LOOP_START:
    setp.ge.u32 %p2, %r6, %r5;
    @%p2 bra END_LOOP;

    // Load A[row, i]
    mul.wide.u32 %rd7, %r6, 2;        // byte offset = i * 2
    add.u64 %rd8, %rd6, %rd7;
    ld.global.f16 %h1, [%rd8];

    // Load B[i]
    add.u64 %rd9, %rd2, %rd7;
    ld.global.f16 %h2, [%rd9];

    // Convert to FP32 and multiply‑accumulate
    cvt.f32.f16 %f1, %h1;
    cvt.f32.f16 %f2, %h2;
    fma.rn.f32 %f0, %f1, %f2, %f0;

    // i += 256 (blockDim.x)
    add.u32 %r6, %r6, 256;
    bra LOOP_START;

END_LOOP:

    // ------------------------------
    // Block‑wide reduction (shared memory)
    // ------------------------------
    .shared .align 4 .b32 shmem[256];

    // Store per‑lane sum into shared memory
    st.shared.b32 [shmem+%r4*4], %f0;
    bar.sync 0;

    // Binary‑tree reduction
    mov.u32 %r7, 128;                 // stride
REDU_LOOP:
    setp.ge.u32 %p1, %r4, %r7;
    @%p1 bra SKIP_ADD;

    // idx = lane
    // partner = lane + stride
    add.u32 %r8, %r4, %r7;            // partner index
    ld.shared.b32 %f1, [shmem+%r8*4];
    ld.shared.b32 %f2, [shmem+%r4*4];
    add.f32 %f2, %f2, %f1;
    st.shared.b32 [shmem+%r4*4], %f2;
SKIP_ADD:
    bar.sync 0;
    shr.u32 %r7, %r7, 1;              // stride >>= 1
    setp.ne.u32 %p1, %r7, 0;
    @%p1 bra REDU_LOOP;

    // ------------------------------
    // Write result (lane 0)
    // ------------------------------
    setp.eq.u32 %p1, %r4, 0;
    @%p1 {
        ld.shared.b32 %f0, [shmem];
        // Convert FP32 result back to FP16
        cvt.rn.f16.f32 %h1, %f0;

        // C[row] = result
        mul.wide.u32 %rd10, %r3, 2;          // row * sizeof(fp16)
        add.u64 %rd11, %rd3, %rd10;
        st.global.f16 [%rd11], %h1;
    }

    ret;
}
"""

# ------------------------------------------------------------
# Python wrapper that loads and launches the PTX kernel
# ------------------------------------------------------------
import torch

class ModelNew:
    def __init__(self):
        # Load the PTX module using the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        A : (M, K) fp16 tensor on CUDA
        B : (K, 1) fp16 tensor on CUDA
        Returns C : (M, 1) fp16 tensor on CUDA
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        assert B.shape == (K, 1)

        C = torch.empty((M, 1), dtype=torch.float16, device=A.device)

        # Launch configuration: one block per output row, 256 threads per block
        grid  = (M, 1, 1)
        block = (256, 1, 1)

        # Arguments must be provided in the order declared in the PTX entry
        args = [A, B, C, M, K]

        # Invoke the kernel
        ptx_launch(self.module, "matvec_fp16", grid, block, args)

        return C
